"use strict";document.addEventListener("DOMContentLoaded",init);function init(){const e=document.querySelectorAll(".noscript");e.forEach(e=>e.classList.remove("noscript"));const t=document.querySelectorAll("button[data-copytext]");t.forEach(e=>{e.addEventListener("click",()=>{const t=e.dataset.copytext;navigator.clipboard.writeText(t),e.textContent="Link Copied!",e.ariaLive="off",e.blur(),setTimeout(function(){e.textContent="Copy Link",e.ariaLive="assertive"},3e3)})})}